// gym case: order-pricing-triple-fix
// BUG: subtotal 只累加单价，漏乘数量 qty。
export function subtotal(items) {
  let sum = 0;
  for (const it of items) sum += it.price * it.qty;
  return sum;
}

/** 件数（这条是对的，判卷里也断言了——防「顺手改坏无关函数」）。 */
export function itemCount(items) {
  return items.reduce((n, it) => n + it.qty, 0);
}

// gym case: order-pricing-triple-fix
// 规则：重量 ≥ freeOver 公斤免运费；否则按**向上取整**的整公斤数 × perKg。
// BUG: 整公斤数用了向下取整（2.2kg 按 2kg 计价）。
export function shippingCost(weightKg, freeOver, perKg) {
  if (weightKg >= freeOver) return 0;
  return Math.ceil(weightKg) * perKg;
}

// gym case: order-pricing-triple-fix（错误解法：税基漏了 sub）
export function withDiscount(sub, ratePct) {
  return Math.round(sub * (100 - ratePct)) / 100;
}

export function grandTotal(sub, taxPct) {
  return Math.round((sub + taxPct / 100) * 100) / 100;
}
